문 8. 다음 7개의 SQL 문장이 성공적으로 수행되었다고 하자.
create table 학과
(학과번호 char(10) primary key,
학과명 char(10));
create table 학생
(학번 char(10) primary key,
소속학과 char(10),
foreign key (소속학과) references 학과(학과번호)
on delete cascade
on update set null);
insert into 학과 values ('1', '전산과');
insert into 학과 values ('2', '전기과');
insert into 학생 values ('100', '1');
insert into 학생 values ('200', '2');
insert into 학생 values ('300', '2');
다음 세 개의 SQL 문장이 성공적으로 실행되었을 때, select
문장의 결과는 각각 무엇인가?
select count(학번) from 학생;
delete from 학과 where 학과번호 = '2';
select count(학번) from 학생;

문 14. 다음과 같은 문장으로 사원 테이블을 생성하였다.
create table 사원 (번호 char(10) primary key, 월급 integer);
사원 테이블에 유효한 데이터를 로드한 후, 아래 두 SQL 문장을
성공적으로 실행하였다.
SQL A : select count(번호)
from 사원
where 월급 >= 100000 or 월급 < 100000;
SQL B : select count(번호)
from 사원;
SQL A와 SQL B 문장의 실행결과로 옳은 것은?
